# -*- coding: utf-8 -*-
"""
RenderMan Node Wrangler v8.2
- Step 1 : pick an existing PxrSurface OR create new + drag-drop textures
- Step 2 : PxrLayerSurface system (collapsible) — combine two PxrSurfaces
            into a layered material with full texture re-routing
"""
import os
import re
import shutil
import base64
import maya.cmds as cmds
import maya.mel as mel

try:
    from PySide6 import QtWidgets, QtCore, QtGui
except ImportError:
    try:
        from PySide2 import QtWidgets, QtCore, QtGui
    except ImportError:
        cmds.error("No compatible PySide library found.")

RMAN_WRANGLER_UI = None

# =============================================================================
# CUSTOM ICON (BASE64)
# =============================================================================
icon_base64 = ""

# =============================================================================
# TEXTURE DETECTION RULES
# =============================================================================
TEXTURE_RULES = [
    (r'color|diffuse|albedo|base_col|basecolor', 'diffuseColor',      'resultRGB', True,  'PxrTexture'),
    (r'roughness|rough|_rgh',                    'specularRoughness', 'resultR',   False, 'roughness_group'),
    (r'normal|nrm|nor|_nml',                     'bumpNormal',        'resultN',   False, 'PxrNormalMap'),
    (r'metallic|metalness|metal|_mtl',           'specularFaceColor', 'resultRGB', False, 'PxrTexture'),
    (r'emissive|emission|emit',                  'glowColor',         'resultRGB', True,  'PxrTexture'),
]

# Maps a PxrSurface attribute to the corresponding PxrLayer attribute.
SURFACE_TO_LAYER_ATTR = {
    'diffuseColor':      'diffuseColor',
    'specularRoughness': 'primarySpecularRoughness',
    'bumpNormal':        'bumpNormal',
    'specularFaceColor': 'primarySpecularFaceColor',
    'specularEdgeColor': 'primarySpecularEdgeColor',
    'glowColor':         'glowColor',
}

def detect_texture_type(filepath):
    base = os.path.basename(filepath).lower()
    for pattern, target_attr, out_attr, linearize, node_type in TEXTURE_RULES:
        if re.search(pattern, base):
            return {'target_attr': target_attr, 'out_attr': out_attr,
                    'linearize': linearize, 'node_type': node_type}
    return None


# =============================================================================
# DEFAULT SPECULAR VALUES  (HSV 0, 0, 0.5  →  RGB 0.5, 0.5, 0.5)
# =============================================================================
DEFAULT_SPEC = (0.5, 0.5, 0.5)

DEFAULT_SPEC_ATTRS = [
    ('specularFaceColor', DEFAULT_SPEC),
    ('specularEdgeColor', DEFAULT_SPEC),
]


# =============================================================================
# RENDERMAN SHADER LOGIC
# =============================================================================
class RenderManShaderLogic:

    @staticmethod
    def ensure_plugin():
        if not cmds.pluginInfo('RenderMan_for_Maya', query=True, loaded=True):
            cmds.loadPlugin('RenderMan_for_Maya')

    @staticmethod
    def get_pxr_surfaces():
        return cmds.ls(type='PxrSurface') or []

    @staticmethod
    def get_pxr_layer_surfaces():
        return cmds.ls(type='PxrLayerSurface') or []

    @staticmethod
    def apply_default_specular(surface):
        for attr, val in DEFAULT_SPEC_ATTRS:
            try:
                cmds.setAttr(
                    "{}.{}".format(surface, attr),
                    val[0], val[1], val[2], type='double3')
            except Exception:
                pass

    @staticmethod
    def _connect_sg(surface, sg):
        try:
            cmds.connectAttr("{}.outColor".format(surface),
                             "{}.surfaceShader".format(sg), force=True)
        except Exception as e:
            cmds.warning("surfaceShader: {}".format(e))

        try:
            if not cmds.attributeQuery('rman__surface', node=sg, exists=True):
                cmds.addAttr(sg, longName='rman__surface',
                             attributeType='message')
            cmds.connectAttr("{}.message".format(surface),
                             "{}.rman__surface".format(sg), force=True)
        except Exception as e:
            cmds.warning("rman__surface: {}".format(e))

    @classmethod
    def get_or_create_surface(cls, base_name, existing_surface=None):
        cls.ensure_plugin()

        if existing_surface and cmds.objExists(existing_surface):
            surface = existing_surface
            sg = None
            conns = cmds.listConnections(
                "{}.outColor".format(surface),
                type='shadingEngine', destination=True) or []
            if conns:
                sg = conns[0]
            if not sg:
                sg = cmds.sets(renderable=True, noSurfaceShader=True,
                               empty=True, name="{}_SG".format(surface))
                cls._connect_sg(surface, sg)
        else:
            surface = cmds.shadingNode(
                'PxrSurface', asShader=True, name="{}_mat".format(base_name))
            sg = cmds.sets(renderable=True, noSurfaceShader=True,
                           empty=True, name="{}_SG".format(base_name))
            cls._connect_sg(surface, sg)

        cls.apply_default_specular(surface)
        return surface, sg

    @classmethod
    def connect_textures(cls, surface, textures):
        base = surface.replace('_mat', '')
        manifold = cmds.shadingNode(
            'PxrManifold2D', asUtility=True,
            name="{}_manifold".format(base))

        for filepath, info in textures.items():
            if not info:
                continue
            cls._wire_one_texture(base, filepath, info, surface, manifold,
                                  dest_attr_override=None)

    @staticmethod
    def _wire_one_texture(base_name, filepath, info, dest_node,
                          manifold, dest_attr_override=None):
        nt          = info['node_type']
        target_attr = dest_attr_override or info['target_attr']

        if nt == 'roughness_group':
            tex = cmds.shadingNode(
                'PxrTexture', asUtility=True,
                name="{}_roughness_tex".format(base_name))
            cmds.setAttr("{}.filename".format(tex), filepath, type='string')

            remap = cmds.shadingNode(
                'PxrRemap', asUtility=True,
                name="{}_roughness_remap".format(base_name))

            cmds.connectAttr("{}.result".format(manifold),
                             "{}.manifold".format(tex), force=True)
            cmds.connectAttr("{}.resultRGB".format(tex),
                             "{}.inputRGB".format(remap), force=True)
            cmds.connectAttr("{}.resultR".format(remap),
                             "{}.{}".format(dest_node, target_attr), force=True)
        else:
            node_name = "{}_{}_tex".format(base_name, target_attr)
            tex = cmds.shadingNode(nt, asUtility=True, name=node_name)
            cmds.setAttr("{}.filename".format(tex), filepath, type='string')

            if nt == 'PxrNormalMap':
                fn = os.path.basename(filepath).lower()
                try:
                    cmds.setAttr(
                        "{}.orientation".format(tex),
                        1 if ('dx' in fn or 'directx' in fn) else 0)
                except Exception:
                    pass
            elif info['linearize']:
                try:
                    cmds.setAttr("{}.linearize".format(tex), 1)
                except Exception:
                    pass

            cmds.connectAttr("{}.result".format(manifold),
                             "{}.manifold".format(tex), force=True)
            cmds.connectAttr(
                "{}.{}".format(tex, info['out_attr']),
                "{}.{}".format(dest_node, target_attr),
                force=True)

    @staticmethod
    def assign_to_selection(sg):
        sel = cmds.ls(selection=True)
        if not sel:
            cmds.warning("Nothing selected.")
            return False
        try:
            cmds.sets(sel, edit=True, forceElement=sg)
            return True
        except Exception as e:
            cmds.warning("Assign failed: {}".format(e))
            return False

    @classmethod
    def build_layer_shader(cls, base_surface, layer1_surface,
                           layer_surface_node):
        cls.ensure_plugin()

        for node in (base_surface, layer1_surface, layer_surface_node):
            if not cmds.objExists(node):
                raise RuntimeError("Node not found: {}".format(node))

        ls_type = cmds.objectType(layer_surface_node)
        if ls_type != 'PxrLayerSurface':
            raise RuntimeError(
                "'{}' is a '{}', expected PxrLayerSurface.".format(
                    layer_surface_node, ls_type))

        # ── 1. Create PxrLayerMixer and PxrLayers ──────────────────────
        base_n = base_surface.replace('_mat', '')
        l1_n = layer1_surface.replace('_mat', '')

        mixer_node = cmds.shadingNode('PxrLayerMixer', asUtility=True, name="{}_to_{}_Mixer".format(base_n, l1_n))
        layer_base_node = cmds.shadingNode('PxrLayer', asUtility=True, name="{}_PxrLayer".format(base_n))
        layer_1_node = cmds.shadingNode('PxrLayer', asUtility=True, name="{}_PxrLayer".format(l1_n))

        # ── 2. Connect PxrLayers to PxrLayerMixer ──────────────────────
        try:
            cmds.connectAttr("{}.pxrMaterialOut".format(layer_base_node), "{}.baselayer".format(mixer_node), force=True)
        except Exception as e: cmds.warning("Mixer baselayer connection error: {}".format(e))

        try:
            cmds.connectAttr("{}.pxrMaterialOut".format(layer_1_node), "{}.layer1".format(mixer_node), force=True)
        except Exception as e: cmds.warning("Mixer layer1 connection error: {}".format(e))

        # ── 3. Connect PxrLayerMixer to PxrLayerSurface ────────────────
        try:
            cmds.connectAttr("{}.pxrMaterialOut".format(mixer_node), "{}.inputMaterial".format(layer_surface_node), force=True)
        except Exception as e: cmds.warning("LayerSurface inputMaterial connection error: {}".format(e))

        # ── 4. Configure internal PxrLayer sub-nodes ───────────────────
        for sub in [layer_base_node, layer_1_node]:
            # Enable primary specular
            for en_attr in ['enablePrimarySpecular', 'primarySpecularEnable', 'specularEnable']:
                try: cmds.setAttr("{}.{}".format(sub, en_attr), 1)
                except Exception: pass

            # Set Gain to 1.0
            for gain_attr in ['primarySpecularGain', 'specularGain']:
                try: cmds.setAttr("{}.{}".format(sub, gain_attr), 1.0)
                except Exception: pass

            # Specular colours
            for face_attr in ['primarySpecularFaceColor', 'specularFaceColor']:
                try: cmds.setAttr("{}.{}".format(sub, face_attr), 0.5, 0.5, 0.5, type='double3')
                except Exception: pass
            
            for edge_attr in ['primarySpecularEdgeColor', 'specularEdgeColor']:
                try: cmds.setAttr("{}.{}".format(sub, edge_attr), 0.5, 0.5, 0.5, type='double3')
                except Exception: pass

        # ── 5. Re-route existing texture connections ───────────────────
        cls._reroute_textures(base_surface, layer_base_node)
        cls._reroute_textures(layer1_surface, layer_1_node)

        return layer_surface_node

    @staticmethod
    def _reroute_textures(src_surface, dest_layer_node):
        DISPLACEMENT_ATTRS = {'displacementShader', 'displacement',
                              'dispInput', 'dispAmount'}

        all_attrs = cmds.listAttr(src_surface, connectable=True) or []
        for attr in all_attrs:
            if attr in DISPLACEMENT_ATTRS:
                continue

            plug = "{}.{}".format(src_surface, attr)
            try:
                conns = cmds.listConnections(
                    plug, source=True, destination=False,
                    plugs=True) or []
            except Exception:
                continue

            if not conns:
                continue

            dest_attr = SURFACE_TO_LAYER_ATTR.get(attr, attr)
            if not cmds.attributeQuery(dest_attr, node=dest_layer_node, exists=True):
                # Fallback to original attribute name if mapping fails
                if cmds.attributeQuery(attr, node=dest_layer_node, exists=True):
                    dest_attr = attr
                else:
                    continue

            src_plug  = conns[0]
            dest_plug = "{}.{}".format(dest_layer_node, dest_attr)

            existing = cmds.listConnections(
                dest_plug, source=True, destination=False,
                plugs=True) or []
            if existing and existing[0] == src_plug:
                continue

            try:
                cmds.connectAttr(src_plug, dest_plug, force=True)
            except Exception as e:
                cmds.warning(
                    "Re-route {} → {}: {}".format(src_plug, dest_plug, e))


# =============================================================================
# TEXTURE DROP ZONE
# =============================================================================
class TextureDropZone(QtWidgets.QListWidget):
    files_dropped = QtCore.Signal(list)

    def __init__(self, parent=None):
        super(TextureDropZone, self).__init__(parent)
        self.setAcceptDrops(True)
        self.setDragDropMode(QtWidgets.QAbstractItemView.DropOnly)
        self.setSelectionMode(QtWidgets.QAbstractItemView.ExtendedSelection)
        self.setMinimumHeight(120)
        self.setStyleSheet(
            "QListWidget{border:2px dashed #555;background:#252525;color:#ccc;"
            "font-size:12px;} QListWidget::item{padding:2px;}")

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        event.acceptProposedAction()

    def dropEvent(self, event):
        if event.mimeData().hasUrls():
            paths = [u.toLocalFile() for u in event.mimeData().urls()]
            self.files_dropped.emit(paths)
            event.acceptProposedAction()


# =============================================================================
# COLLAPSIBLE SECTION WIDGET
# =============================================================================
class CollapsibleSection(QtWidgets.QWidget):
    def __init__(self, title, collapsed=True, parent=None):
        super(CollapsibleSection, self).__init__(parent)

        self._collapsed = collapsed
        self._main_layout = QtWidgets.QVBoxLayout(self)
        self._main_layout.setContentsMargins(0, 0, 0, 0)
        self._main_layout.setSpacing(0)

        self._toggle_btn = QtWidgets.QPushButton()
        self._toggle_btn.setCheckable(True)
        self._toggle_btn.setChecked(not collapsed)
        self._toggle_btn.setFlat(True)
        self._toggle_btn.setCursor(QtCore.Qt.PointingHandCursor)
        self._toggle_btn.setStyleSheet(
            "QPushButton{text-align:left;background:#2a2a2a;color:#9cf;"
            "font-weight:bold;border:1px solid #444;border-radius:4px;"
            "padding:5px 8px;font-size:12px;}"
            "QPushButton:hover{background:#333;}")
        self._update_title(title)
        self._main_layout.addWidget(self._toggle_btn)

        self._content = QtWidgets.QWidget()
        self._content_layout = QtWidgets.QVBoxLayout(self._content)
        self._content_layout.setContentsMargins(4, 4, 4, 4)
        self._content_layout.setSpacing(6)
        self._content.setVisible(not collapsed)

        self._content.setStyleSheet(
            "QWidget{border-left:2px solid #3a4a5a;margin-left:4px;}")
        self._main_layout.addWidget(self._content)

        self._toggle_btn.toggled.connect(self._on_toggle)
        self._title = title

    def _update_title(self, title):
        arrow = "▼" if (not self._collapsed) else "▶"
        self._toggle_btn.setText("  {}  {}".format(arrow, title))

    def _on_toggle(self, checked):
        self._collapsed = not checked
        self._update_title(self._title)
        self._content.setVisible(checked)

    def add_widget(self, widget):
        self._content_layout.addWidget(widget)

    def add_layout(self, layout):
        self._content_layout.addLayout(layout)

    def content_layout(self):
        return self._content_layout


