    # ── Feedback System ───────────────────────────────────────────────────────
    def _log(self, msg, level="info"):
        color = "#ccc"
        prefix = ""
        if level == "success": color = "#55ff55"; prefix = "[OK] "
        elif level == "warning": color = "#ffaa00"; prefix = "[WARN] "
        elif level == "error": color = "#ff5555"; prefix = "[ERR] "
            
        self.feedback_log.append("<span style='color:{};'>{}{}</style>".format(color, prefix, msg))
        sb = self.feedback_log.verticalScrollBar()
        sb.setValue(sb.maximum())

    def _clear_feedback(self):
        self.feedback_log.clear()

    # ── Step 1 group ──────────────────────────────────────────────────────────
    def _build_step1(self):
        s1 = QtWidgets.QGroupBox("  Step 1  —  Target PxrSurface")
        s1.setStyleSheet(GROUP_STYLE)
        s1l = QtWidgets.QVBoxLayout(s1)
        s1l.setSpacing(6)

        row_dd = QtWidgets.QHBoxLayout()
        self.surface_combo = _make_combo()
        self.surface_combo.setMinimumWidth(240)
        btn_refresh = _make_refresh_btn()
        row_dd.addWidget(QtWidgets.QLabel("Scene shaders:"))
        row_dd.addWidget(self.surface_combo)
        row_dd.addWidget(btn_refresh)
        s1l.addLayout(row_dd)

        self.surface_info = QtWidgets.QLabel("Select an existing PxrSurface OR leave on '— Create new —'")
        self.surface_info.setStyleSheet("color:#888;font-style:italic;font-size:11px;")
        s1l.addWidget(self.surface_info)

        row_name = QtWidgets.QHBoxLayout()
        self.lbl_name   = QtWidgets.QLabel("New material name:")
        self.name_input = QtWidgets.QLineEdit("custom_material")
        self.name_input.setStyleSheet("background:#2e2e2e;color:#ddd;border:1px solid #555;padding:3px;border-radius:3px;")
        row_name.addWidget(self.lbl_name)
        row_name.addWidget(self.name_input)
        s1l.addLayout(row_name)

        btn_refresh.clicked.connect(self._refresh_surfaces)
        self.surface_combo.currentIndexChanged.connect(self._on_combo_changed)
        return s1

    # ── Step 2 group ──────────────────────────────────────────────────────────
    def _build_step2(self):
        s2 = QtWidgets.QGroupBox("  Step 2  —  Texture Maps")
        s2.setStyleSheet(GROUP_STYLE)
        s2l = QtWidgets.QVBoxLayout(s2)
        s2l.setSpacing(6)

        hint = QtWidgets.QLabel("Drag & drop texture files or a folder here")
        hint.setStyleSheet("color:#888;font-size:11px;font-style:italic;")
        hint.setAlignment(QtCore.Qt.AlignCenter)
        s2l.addWidget(hint)

        self.tex_zone = TextureDropZone()
        self.tex_zone.files_dropped.connect(self._on_textures_dropped)
        s2l.addWidget(self.tex_zone)
        return s2

    # ── Layer Surface section ─────────────────────────────────────────────────
    def _build_layer_section(self):
        self._layer_section = CollapsibleSection("PxrLayerSurface — Layered Material", collapsed=True)
        desc = QtWidgets.QLabel("Combine two existing PxrSurface nodes into a PxrLayerSurface.\nTexture connections are automatically re-routed to the correct layers.")
        desc.setStyleSheet("color:#888;font-size:11px;font-style:italic;")
        desc.setWordWrap(True)
        self._layer_section.add_widget(desc)

        row_base = QtWidgets.QHBoxLayout()
        row_base.addWidget(QtWidgets.QLabel("Base Layer:"))
        self.layer_base_combo = _make_combo()
        row_base.addWidget(self.layer_base_combo)
        btn_r1 = _make_refresh_btn()
        btn_r1.clicked.connect(self._refresh_layer_combos)
        row_base.addWidget(btn_r1)
        self._layer_section.add_layout(row_base)

        row_l1 = QtWidgets.QHBoxLayout()
        row_l1.addWidget(QtWidgets.QLabel("Layer 1:     "))
        self.layer_l1_combo = _make_combo()
        row_l1.addWidget(self.layer_l1_combo)
        self._layer_section.add_layout(row_l1)

        row_ls = QtWidgets.QHBoxLayout()
        row_ls.addWidget(QtWidgets.QLabel("PxrLayerSurface:"))
        self.layer_ls_combo = _make_combo()
        row_ls.addWidget(self.layer_ls_combo)
        btn_r2 = _make_refresh_btn()
        btn_r2.clicked.connect(self._refresh_layer_combos)
        row_ls.addWidget(btn_r2)
        self._layer_section.add_layout(row_ls)

        self.btn_build_layer = QtWidgets.QPushButton("Build Layer Shader")
        self.btn_build_layer.setStyleSheet("background:#6b3a8f;color:white;font-weight:bold;padding:8px;border-radius:4px;font-size:13px;")
        self.btn_build_layer.clicked.connect(self._action_build_layer)
        self._layer_section.add_widget(self.btn_build_layer)

        self.btn_assign_layer = QtWidgets.QPushButton("Assign Layer Shader to Selection")
        self.btn_assign_layer.setEnabled(False)
        self.btn_assign_layer.setStyleSheet("background:#444;color:#999;border:1px solid #555;padding:6px;border-radius:4px;font-weight:bold;")
        self.btn_assign_layer.clicked.connect(self._action_assign_layer)
        self._layer_section.add_widget(self.btn_assign_layer)

        self._last_layer_sg = None
        self._refresh_layer_combos()
        return self._layer_section

    # ── Step 1 helpers ────────────────────────────────────────────────────────
    def _refresh_surfaces(self):
        self.surface_combo.blockSignals(True)
        self.surface_combo.clear()
        self.surface_combo.addItem("— Create new —", userData=None)
        for s in RenderManShaderLogic.get_pxr_surfaces():
            self.surface_combo.addItem(s, userData=s)
        self.surface_combo.blockSignals(False)
        self._on_combo_changed(self.surface_combo.currentIndex())

    def _on_combo_changed(self, idx):
        data = self.surface_combo.itemData(idx)
        self.selected_surface = data
        if data is None:
            self.surface_info.setText("A new PxrSurface + SG will be created automatically.")
            self.surface_info.setStyleSheet("color:#888;font-style:italic;font-size:11px;")
            self.lbl_name.setVisible(True)
            self.name_input.setVisible(True)
            self.btn_assign_selected.setEnabled(False)
            self.btn_assign_selected.setText("Assign material to selection")
            self.btn_assign_selected.setStyleSheet("background:#444;color:#999;border:1px solid #555;padding:8px;border-radius:4px;font-weight:bold;font-size:12px;")
        else:
            self.surface_info.setText("Selected Material: {}".format(data))
            self.surface_info.setStyleSheet("color:#5af;font-style:normal;font-size:11px;")
            self.lbl_name.setVisible(False)
            self.name_input.setVisible(False)
            self.btn_assign_selected.setEnabled(True)
            self.btn_assign_selected.setText("Assign '{}' to selection".format(data))
            self.btn_assign_selected.setStyleSheet("background:#2b5c6f;color:#ddf;border:1px solid #3a7a9f;padding:8px;border-radius:4px;font-weight:bold;font-size:12px;")

    # ── Step 2 helpers ────────────────────────────────────────────────────────
    def _on_textures_dropped(self, paths):
        for path in paths:
            path = path.replace('\\', '/')
            if os.path.isdir(path):
                for root, _, files in os.walk(path):
                    for f in files:
                        if f.lower().endswith(self.VALID_EXT):
                            self._add_texture(os.path.join(root, f).replace('\\', '/'))
            elif os.path.isfile(path) and path.lower().endswith(self.VALID_EXT):
                self._add_texture(path)

        if paths and self.selected_surface is None:
            first = os.path.basename(paths[0]).split('.')[0]
            first = re.sub(r'[_\-](color|diffuse|albedo|basecolor|roughness|rough|normal|nrm|metal|metallic|emit|emission).*', '', first, flags=re.IGNORECASE)
            self.name_input.setText(first)

    def _add_texture(self, filepath):
        if filepath in self.textures: return
        info = detect_texture_type(filepath)
        self.textures[filepath] = info
        fname = os.path.basename(filepath)
        tag   = info['target_attr'] if info else "ignored"
        item  = QtWidgets.QListWidgetItem("  [{:<22}]  {}".format(tag, fname))
        item.setToolTip(filepath)
        item.setData(QtCore.Qt.UserRole, filepath)
        item.setForeground(QtGui.QColor('#ddd') if info else QtGui.QColor('#666'))
        self.tex_zone.addItem(item)

    # ── Layer helpers ─────────────────────────────────────────────────────────
    def _refresh_layer_combos(self):
        surfaces = RenderManShaderLogic.get_pxr_surfaces()
        ls_nodes = RenderManShaderLogic.get_pxr_layer_surfaces()

        for combo in (self.layer_base_combo, self.layer_l1_combo):
            combo.blockSignals(True)
            combo.clear()
            combo.addItem("— select —", userData=None)
            for s in surfaces: combo.addItem(s, userData=s)
            combo.blockSignals(False)

        self.layer_ls_combo.blockSignals(True)
        self.layer_ls_combo.clear()
        self.layer_ls_combo.addItem("— select —", userData=None)
        for ls in ls_nodes: self.layer_ls_combo.addItem(ls, userData=ls)
        self.layer_ls_combo.blockSignals(False)

    # ── Actions ───────────────────────────────────────────────────────────────
    def _action_build(self):
        if not self.textures:
            self._log("No textures loaded in Step 2.", level="warning")
            return

        base = self.name_input.text().strip() or "RM_Shader"
        try:
            surface, sg = RenderManShaderLogic.get_or_create_surface(base, existing_surface=self.selected_surface)
            RenderManShaderLogic.connect_textures(surface, self.textures)

            self._log("Shader '{}' built successfully!".format(surface), level="success")
            
            self.textures.clear()
            self.tex_zone.clear()
            self._refresh_surfaces()
            self._refresh_layer_combos()

            idx = self.surface_combo.findData(surface)
            if idx >= 0: self.surface_combo.setCurrentIndex(idx)

        except Exception as e:
            import traceback
            self._log("Build error: {}".format(e), level="error")
            cmds.error("Build error: {}\n{}".format(e, traceback.format_exc()))

    def _action_assign_selected(self):
        if not self.selected_surface:
            self._log("No material selected.", level="warning")
            return
        _, sg = RenderManShaderLogic.get_or_create_surface(self.selected_surface, existing_surface=self.selected_surface)
        if sg and RenderManShaderLogic.assign_to_selection(sg):
            self._log("Assigned '{}' to selection.".format(self.selected_surface), level="success")

    def _action_build_layer(self):
        base_surf = self.layer_base_combo.currentData()
        l1_surf   = self.layer_l1_combo.currentData()
        ls_node   = self.layer_ls_combo.currentData()

        errors = []
        if not base_surf: errors.append("• Base Layer: no PxrSurface selected.")
        if not l1_surf: errors.append("• Layer 1: no PxrSurface selected.")
        if not ls_node: errors.append("• PxrLayerSurface: no node selected.")
        if base_surf and l1_surf and base_surf == l1_surf: errors.append("• Base Layer and Layer 1 must be different nodes.")
        
        if errors:
            self._log("Build Layer Shader failed. Check inputs.", level="warning")
            cmds.warning("Build Layer Shader — please fix:\n" + "\n".join(errors))
            return

        try:
            RenderManShaderLogic.build_layer_shader(base_surf, l1_surf, ls_node)

            sg = None
            conns = cmds.listConnections("{}.outColor".format(ls_node), type='shadingEngine', destination=True) or []
            if conns: sg = conns[0]
            if not sg:
                sg = cmds.sets(renderable=True, noSurfaceShader=True, empty=True, name="{}_SG".format(ls_node))
                RenderManShaderLogic._connect_sg(ls_node, sg)

            self._last_layer_sg = sg
            self.btn_assign_layer.setEnabled(True)
            self.btn_assign_layer.setStyleSheet("background:#6b3a8f;color:white;border:1px solid #9a5abf;padding:6px;border-radius:4px;font-weight:bold;")
            self.btn_assign_layer.setText("Assign '{}' to selection".format(ls_node))

            self._log("Layer shader built successfully: {} → {}".format(ls_node, sg), level="success")

        except Exception as e:
            import traceback
            self._log("Layer build error: {}".format(e), level="error")
            cmds.error("Layer build error: {}\n{}".format(e, traceback.format_exc()))

    def _action_assign_layer(self):
        if self._last_layer_sg:
            if RenderManShaderLogic.assign_to_selection(self._last_layer_sg):
                self._log("Layer shader assigned to selection.", level="success")

    def _reset(self):
        self.textures.clear()
        self.tex_zone.clear()
        self.selected_surface = None
        self._last_layer_sg   = None
        self.btn_assign_layer.setEnabled(False)
        self.btn_assign_layer.setText("Assign Layer Shader to Selection")
        self.btn_assign_layer.setStyleSheet("background:#444;color:#999;border:1px solid #555;padding:6px;border-radius:4px;font-weight:bold;")
        self._refresh_surfaces()
        self._refresh_layer_combos()
        self._log("Textures and UI state cleared.", level="info")

    def _action_lighting(self):
        try:
            cmds.setAttr("defaultResolution.width",  3840)
            cmds.setAttr("defaultResolution.height", 2160)
            RenderManShaderLogic.ensure_plugin()
            cmds.setAttr("defaultRenderGlobals.currentRenderer", "renderman", type="string")
            if not cmds.objExists('rmanGlobals'):
                try: mel.eval('rmanCreateGlobals()')
                except Exception: pass
            for attr in ["maxSamples", "hider_maxSamples"]:
                if cmds.objExists("rmanGlobals." + attr):
                    cmds.setAttr("rmanGlobals." + attr, 256)
                    break
            self._log("Default Lighting Setup applied!", level="success")
        except Exception as e:
            self._log("Lighting Setup error: {}".format(e), level="error")

    def _action_color(self):
        try:
            cmds.colorManagementPrefs(edit=True, cmEnabled=True)
            try:
                cmds.colorManagementPrefs(edit=True, configFilePath=("<MAYA_RESOURCES>/OCIO-configs/Maya2022-default/config.ocio"))
                cmds.colorManagementPrefs(edit=True, cmConfigFileEnabled=True)
            except Exception: pass
            try: cmds.colorManagementPrefs(edit=True, renderingSpaceName="scene-linear Rec.709-sRGB")
            except Exception as e: cmds.warning("Rendering space: {}".format(e))
            
            views = cmds.colorManagementPrefs(query=True, viewTransformNames=True) or []
            for v in ["Un-tone-mapped (sRGB)", "Un-tone-mapped", "Untonemapped", "Raw"]:
                if v in views:
                    cmds.colorManagementPrefs(edit=True, viewTransformName=v)
                    break
            self._log("Color Correction Workspace applied!", level="success")
        except Exception as e:
            self._log("Color Workspace error: {}".format(e), level="error")

