def show_ui():
    global RMAN_WRANGLER_UI
    if RMAN_WRANGLER_UI is not None:
        try:
            RMAN_WRANGLER_UI.close()
            RMAN_WRANGLER_UI.deleteLater()
        except Exception:
            pass
    RMAN_WRANGLER_UI = NodeWranglerUI()
    RMAN_WRANGLER_UI.show()

def onMayaDroppedPythonFile(*args):
    try:
        source_path = args[0] if (args and args[0]) else None
        if not source_path or not os.path.exists(source_path):
            res = cmds.fileDialog2(fileMode=1, caption="Locate rman_node_wrangler.py", fileFilter="Python Files (*.py)")
            source_path = res[0] if res else None
        if not source_path:
            show_ui()
            return

        script_dir  = cmds.internalVar(userScriptDir=True)
        dest_path   = os.path.join(script_dir, "rman_node_wrangler.py")
        module_name = "rman_node_wrangler"
        if os.path.normpath(source_path) != os.path.normpath(dest_path):
            shutil.copy2(source_path, dest_path)

        icon_dir  = cmds.internalVar(userBitmapsDir=True)
        icon_path = os.path.join(icon_dir, "rman_wrangler_icon.png")
        try:
            if icon_base64 != "PASTE_YOUR_BASE64_IMAGE_STRING_HERE":
                with open(icon_path, "wb") as fh:
                    fh.write(base64.b64decode(icon_base64))
            else:
                icon_path = "pythonFamily.png"
        except Exception:
            icon_path = "pythonFamily.png"

        shelf = mel.eval("tabLayout -q -selectTab $gShelfTopLevel")
        cmds.setParent(shelf)
        cmds.shelfButton(
            command=(
                "import sys\n"
                "if '{0}' in sys.modules: del sys.modules['{0}']\n"
                "import {0}\n"
                "{0}.show_ui()".format(module_name)),
            annotation="RenderMan Node Wrangler",
            sourceType="Python",
            image1=icon_path,
            label="RM_Wrang")

        cmds.confirmDialog(
            title="Installation Successful",
            message="RenderMan Node Wrangler added to shelf '{}'.".format(shelf),
            button=["Great!"])
        show_ui()

    except Exception as e:
        cmds.error("Install error: {}".format(e))
        show_ui()

if __name__ == "__main__":
    show_ui()